def dedup(items):
    seen = []
    out = []
    for it in items:
        duplicate = False
        for s in seen:
            try:
                if it is s or it == s:
                    duplicate = True
                    break
            except TypeError:
                # incomparable / mixed types: not a duplicate by equality
                pass
        if not duplicate:
            seen.append(it)
            out.append(it)
    return out

